1	// Shared plan constants — safe for both client and server
2	
3	/**
4	 * Sentinel value used in place of Infinity for "unlimited" plan limits.
5	 * Infinity cannot be serialized to JSON (becomes null), so we use this
6	 * large number as the canonical "no limit" value. All limit comparisons
7	 * should use isUnlimited() or compare against UNLIMITED.
8	 */
9	export const UNLIMITED = 999999;
10	
11	export const PLAN_FREE = "free";
12	export const PLAN_STARTER_MONTHLY = "Starter Monthly";
13	export const PLAN_STARTER_ANNUAL = "Starter Annual";
14	export const PLAN_PRO_MONTHLY = "Pro Monthly";
15	export const PLAN_PRO_ANNUAL = "Pro Annual";
16	export const PLAN_ULTIMATE_MONTHLY = "Ultimate Monthly";
17	export const PLAN_ULTIMATE_ANNUAL = "Ultimate Annual";
18	
19	export const ALL_PAID_PLANS = [
20	  PLAN_STARTER_MONTHLY,
21	  PLAN_STARTER_ANNUAL,
22	  PLAN_PRO_MONTHLY,
23	  PLAN_PRO_ANNUAL,
24	  PLAN_ULTIMATE_MONTHLY,
25	  PLAN_ULTIMATE_ANNUAL,
26	];
27	
28	export type PlanTier = "free" | "starter" | "pro" | "ultimate";
29	
30	export interface PlanLimits {
31	  maxZipCodes: number;
32	  allowBlocked: boolean;
33	  maxDeliveryRules: number;
34	  maxWaitlist: number;
35	  csvImport: boolean;
36	  csvExport: boolean;
37	  widgetBasicCustom: boolean;
38	  widgetFullCustom: boolean;
39	  showEtaCodReturn: boolean;
40	  cartBlocking: boolean;
41	  customCss: boolean;
42	  label: string;
43	}
44	
45	export const PLAN_LIMITS: Record<PlanTier, PlanLimits> = {
46	  free: {
47	    maxZipCodes: 20,
48	    allowBlocked: false,
49	    maxDeliveryRules: 0,
50	    maxWaitlist: 0,
51	    csvImport: false,
52	    csvExport: false,
53	    widgetBasicCustom: true,
54	    widgetFullCustom: false,
55	    showEtaCodReturn: false,
56	    cartBlocking: false,
57	    customCss: false,
58	    label: "Free",
59	  },
60	  starter: {
61	    maxZipCodes: 500,
62	    allowBlocked: true,
63	    maxDeliveryRules: 3,
64	    maxWaitlist: 50,
65	    csvImport: true,
66	    csvExport: false,
67	    widgetBasicCustom: true,
68	    widgetFullCustom: true,
69	    showEtaCodReturn: true,
70	    cartBlocking: false,
71	    customCss: false,
72	    label: "Starter",
73	  },
74	  pro: {
75	    maxZipCodes: UNLIMITED,
76	    allowBlocked: true,
77	    maxDeliveryRules: UNLIMITED,
78	    maxWaitlist: UNLIMITED,
79	    csvImport: true,
80	    csvExport: true,
81	    widgetBasicCustom: true,
82	    widgetFullCustom: true,
83	    showEtaCodReturn: true,
84	    cartBlocking: true,
85	    customCss: false,
86	    label: "Pro",
87	  },
88	  ultimate: {
89	    maxZipCodes: UNLIMITED,
90	    allowBlocked: true,
91	    maxDeliveryRules: UNLIMITED,
92	    maxWaitlist: UNLIMITED,
93	    csvImport: true,
94	    csvExport: true,
95	    widgetBasicCustom: true,
96	    widgetFullCustom: true,
97	    showEtaCodReturn: true,
98	    cartBlocking: true,
99	    customCss: true,
100	    label: "Ultimate",
101	  },
102	};
103	
104	export function getPlanTier(planName: string): PlanTier {
105	  if (planName === PLAN_STARTER_MONTHLY || planName === PLAN_STARTER_ANNUAL)
106	    return "starter";
107	  if (planName === PLAN_PRO_MONTHLY || planName === PLAN_PRO_ANNUAL)
108	    return "pro";
109	  if (planName === PLAN_ULTIMATE_MONTHLY || planName === PLAN_ULTIMATE_ANNUAL)
110	    return "ultimate";
111	  return "free";
112	}
